package vista;
import controlador.LibroController;import dao.CategoriaDAO;import modelo.*;import javax.swing.*;import javax.swing.table.DefaultTableModel;import java.awt.*;import java.util.*;
public class LibrosFrame extends JFrame {private final Usuario usuario;private final LibroController ctrl=new LibroController();private final CategoriaDAO cats=new CategoriaDAO();private final DefaultTableModel model=new DefaultTableModel(new Object[]{"ID","Título","Autor","ISBN","Editorial","Stock","Categoría","ID categoría"},0){public boolean isCellEditable(int r,int c){return false;}};private final JTable table=new JTable(model);
 public LibrosFrame(Usuario u){super("Gestión de libros");usuario=u;setSize(1000,520);setLocationRelativeTo(null);setLayout(new BorderLayout(8,8));add(new JScrollPane(table),BorderLayout.CENTER);JPanel bar=new JPanel();JButton refresh=new JButton("Actualizar"),add=new JButton("Registrar"),edit=new JButton("Modificar"),del=new JButton("Eliminar");bar.add(refresh);if(u.esBibliotecario()){bar.add(add);bar.add(edit);bar.add(del);}add(bar,BorderLayout.SOUTH);refresh.addActionListener(e->load());add.addActionListener(e->form(null));edit.addActionListener(e->{int r=table.getSelectedRow();if(r>=0)form(r);else msg("Selecciona un libro.");});del.addActionListener(e->delete());load();}
 private void msg(String s){JOptionPane.showMessageDialog(this,s);}private void load(){try{model.setRowCount(0);for(Libro l:ctrl.listar())model.addRow(new Object[]{l.getId(),l.getTitulo(),l.getAutor(),l.getIsbn(),l.getEditorial(),l.getStock(),l.getCategoria(),l.getIdCategoria()});}catch(Exception e){msg("Error al cargar libros: "+e.getMessage());}}
 private void form(Integer row){try{java.util.List<Categoria> lista=cats.listar();JComboBox<Categoria> cat=new JComboBox<>(lista.toArray(new Categoria[0]));JTextField[] f={new JTextField(row==null?"":String.valueOf(model.getValueAt(row,1))),new JTextField(row==null?"":String.valueOf(model.getValueAt(row,2))),new JTextField(row==null?"":String.valueOf(model.getValueAt(row,3))),new JTextField(row==null?"":String.valueOf(model.getValueAt(row,4))),new JTextField(row==null?"0":String.valueOf(model.getValueAt(row,5)))};if(row!=null){int id=(int)model.getValueAt(row,7);for(int i=0;i<cat.getItemCount();i++)if(cat.getItemAt(i).getId()==id)cat.setSelectedIndex(i);}JPanel p=new JPanel(new GridLayout(0,2,5,5));String[] labels={"Título","Autor","ISBN","Editorial","Stock","Categoría"};for(int i=0;i<5;i++){p.add(new JLabel(labels[i]));p.add(f[i]);}p.add(new JLabel(labels[5]));p.add(cat);if(JOptionPane.showConfirmDialog(this,p,row==null?"Registrar libro":"Modificar libro",JOptionPane.OK_CANCEL_OPTION)!=JOptionPane.OK_OPTION)return;int stock=Integer.parseInt(f[4].getText().trim());Categoria c=(Categoria)cat.getSelectedItem();if(c==null)throw new IllegalArgumentException("Registra primero una categoría.");Libro l=new Libro(row==null?0:(int)model.getValueAt(row,0),f[0].getText().trim(),f[1].getText().trim(),f[2].getText().trim(),f[3].getText().trim(),stock,c.getId(),c.getNombre());if(row==null)ctrl.guardar(l);else ctrl.actualizar(l);load();}catch(Exception e){msg("No se pudo guardar: "+e.getMessage());}}
 private void delete(){int r=table.getSelectedRow();if(r<0){msg("Selecciona un libro.");return;}if(JOptionPane.showConfirmDialog(this,"¿Eliminar el libro seleccionado?","Confirmar",JOptionPane.YES_NO_OPTION)==JOptionPane.YES_OPTION)try{ctrl.eliminar((int)model.getValueAt(r,0));load();}catch(Exception e){msg(e.getMessage());}}
}